package com.bank.strings;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class StringImmutableDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Immutability: methods return NEW strings, original unchanged.
        String id = "SAV2001";
        String upper = id.toUpperCase(); // new string
        log.info(() -> "original still = " + id + ", derived = " + upper);

        // Safe as HashMap key: hash code is stable because contents never change.
        AccountRegistry registry = new AccountRegistry();
        registry.open("SAV2001", new BigDecimal("1000000.00"));
        registry.open("CUR3001", new BigDecimal("250000.00"));
        log.info(() -> "Lookup SAV2001 balance = " + registry.balanceOf("SAV2001"));

        // Security: validated connection string cannot be mutated afterwards.
        ConnectionValidator validator = new ConnectionValidator();
        String url = "jdbc:postgresql://db.bank.local:5432/accounts";
        validator.openIfValid(url);

        // Pool sharing: identical literals share one object (== is true).
        String a = "SAV2001";
        String b = "SAV2001";
        log.info(() -> "Pooled literals share one object (==): " + (a == b));
    }
}

// ─── Would be AccountRegistry.java in a real project ───
class AccountRegistry {
    private static final Logger log = Logger.getLogger("BankLog");
    private final Map<String, BigDecimal> balances = new HashMap<>(); // String keys
    void open(String accountId, BigDecimal balance) {
        balances.put(accountId, balance); // stable hash code -> reliable bucket
        log.info(() -> "Opened " + accountId + " with " + balance);
    }
    BigDecimal balanceOf(String accountId) { return balances.get(accountId); }
}

// ─── Would be ConnectionValidator.java in a real project ───
class ConnectionValidator {
    private static final Logger log = Logger.getLogger("BankLog");
    void openIfValid(String url) {
        // Validate once...
        if (!url.startsWith("jdbc:postgresql://")) {
            throw new SecurityException("Rejected connection URL");
        }
        // ...and because String is immutable, 'url' cannot change between
        // the check above and the use below (no TOCTOU attack possible).
        log.info(() -> "Opening validated connection to " + url);
    }
}
